-- Update ICD-10 long_desc from /Users/jorgeluisdevera/Downloads/CIE 10.xlsx sheet CIE10
-- Excel Código -> icd10_dx_order_code.dx_code; Excel Etiqueta -> long_desc
-- Generated on 2026-06-12. Review counts before COMMIT if running manually.

SET NAMES utf8mb4;
START TRANSACTION;

DROP TEMPORARY TABLE IF EXISTS tmp_cie10_long_desc;
CREATE TEMPORARY TABLE tmp_cie10_long_desc (
  dx_code varchar(7) NOT NULL PRIMARY KEY,
  long_desc varchar(300) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;






































SELECT COUNT(*) AS excel_codes_loaded FROM tmp_cie10_long_desc;
SELECT COUNT(*) AS matching_db_rows FROM icd10_dx_order_code d JOIN tmp_cie10_long_desc x ON x.dx_code = d.dx_code;
SELECT COUNT(*) AS rows_that_will_change FROM icd10_dx_order_code d JOIN tmp_cie10_long_desc x ON x.dx_code = d.dx_code WHERE COALESCE(d.long_desc, '') <> x.long_desc;

CREATE TABLE icd10_dx_order_code_long_desc_backup_20260612_1018 AS
SELECT d.*
FROM icd10_dx_order_code d
JOIN tmp_cie10_long_desc x ON x.dx_code = d.dx_code
WHERE COALESCE(d.long_desc, '') <> x.long_desc;

UPDATE icd10_dx_order_code d
JOIN tmp_cie10_long_desc x ON x.dx_code = d.dx_code
SET d.long_desc = x.long_desc
WHERE COALESCE(d.long_desc, '') <> x.long_desc;

SELECT ROW_COUNT() AS rows_updated;
SELECT d.dx_code, d.long_desc FROM icd10_dx_order_code d JOIN tmp_cie10_long_desc x ON x.dx_code = d.dx_code ORDER BY d.dx_code LIMIT 10;

COMMIT;
